}

// selected reads one bit out of the staged slice. `bit0` is the block's first
// bit inside its row's first staged word, which is zero on every rung whose
// key block is a whole number of words.
bool selected(uint row, uint col, uint bit0) {
    uint b = bit0 + col;
    return (selw[row * BW + (b >> 5u)] & (1u << (b & 31u))) != 0u;
}

// Which (token, query head) fragment row `r` is, and whether this workgroup
// stores it. Token rows by default; heads on the rows under HROWS.
#ifdef HROWS
#define ROW_TOKEN(r) (q0)
#define ROW_HEAD(r) (h0 + (r))
#define ROW_OK(r) ((h0 + (r)) / rep == kvh)
#else
#define ROW_TOKEN(r) (q0 + (r))
#define ROW_HEAD(r) (head)
#define ROW_OK(r) (q0 + (r) < pc.tokens)
